## Code Example
```javascript
const request = require('supertest');
const app = require('../src/app');

test('idempotent payments with same key yields single ledger write', async () => {
  const key = 'abc123';
  const payload = { amount: 100, currency: 'USD', merchant: 'ACME' };
  const t1 = request(app).post('/payments').set('Idempotency-Key', key).send(payload);
  const t2 = request(app).post('/payments').set('Idempotency-Key', key).send(payload);
  const [r1, r2] = await Promise.all([t1, t2]);
  expect(r1.status).toBe(200);
  expect(r2.status).toBe(200);
  // verify a single ledger entry created via test hooks or API mocks
});
```

